-- ============================================================\n-- STEP 1: Clean up database\n-- Deactivate all items NOT in the new JSON that have NO movements\n-- ============================================================\n\nUPDATE items\nSET is_active = 0\nWHERE company_id = 1\n  AND is_active = 1\n  AND code NOT IN (1010002, 1010004, 1010006, 1010023, 1010060, 1010062, 1010066, 1010071, 1010074, 1010075, 1010095, 1010132, 1010189, 1010327, 1010366, 1010374, 1010436, 1010437, 1010438, 1010439, 1010449, 1080035, 1030002, 1030003, 1030008, 1030229, 1030233, 1030234, 1030259, 1030260, 1030264, 1030265, 1030266, 1030267, 1030274, 1030277, 1040001, 1050092, 1050095, 1050149, 1050197, 1050316, 1050364, 1050401, 1070010, 1070238, 1070245, 1070317, 1070786, 1070844, 1020259, 1020288, 1020361, 1020362, 1020380, 1020393, 1020401, 1090043, 1090168, 1090228, 1090230)\n  AND code NOT IN (\n    SELECT DISTINCT item_code\n    FROM inventory_movements\n    WHERE company_id = 1\n  );\n\n-- ============================================================\n-- STEP 2: Reactivate all 61 items from new JSON\n-- ============================================================\n\nUPDATE items\nSET is_active = 1\nWHERE company_id = 1 AND code IN (1010002, 1010004, 1010006, 1010023, 1010060, 1010062, 1010066, 1010071, 1010074, 1010075, 1010095, 1010132, 1010189, 1010327, 1010366, 1010374, 1010436, 1010437, 1010438, 1010439, 1010449, 1080035, 1030002, 1030003, 1030008, 1030229, 1030233, 1030234, 1030259, 1030260, 1030264, 1030265, 1030266, 1030267, 1030274, 1030277, 1040001, 1050092, 1050095, 1050149, 1050197, 1050316, 1050364, 1050401, 1070010, 1070238, 1070245, 1070317, 1070786, 1070844, 1020259, 1020288, 1020361, 1020362, 1020380, 1020393, 1020401, 1090043, 1090168, 1090228, 1090230);\n